import{_ as e,a as s,c as a,b as o}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"02-stash暂存工作区","description":"","frontmatter":{"title":"02-stash暂存工作区"},"headers":[],"relativePath":"posts/开发经验/Git与版本控制/02-stash暂存工作区.md","filePath":"posts/开发经验/Git与版本控制/02-stash暂存工作区.md"}'),r={name:"posts/开发经验/Git与版本控制/02-stash暂存工作区.md"};function p(i,t,c,g,d,n){return s(),a("div",null,[...t[0]||(t[0]=[o('<h3 id="切换分支前-用-git-stash-安全转移未提交的修改" tabindex="-1">切换分支前，用 <code>git stash</code> 安全转移未提交的修改 <a class="header-anchor" href="#切换分支前-用-git-stash-安全转移未提交的修改" aria-label="Permalink to &quot;切换分支前，用 `git stash` 安全转移未提交的修改&quot;">​</a></h3><p>情景描述：</p><p>当前我处于 master 分支，对文件进行了<strong>修改</strong>，但是没有 commit 提交修改，希望创建一个新的分支，然后提交内容。</p><p>问题：</p><p>如果我当前的内容不存起来的话，直接切换分支，会导致当前的仓库加载分支对应的状态，已经修改的文件会被覆盖，由于没有缓存，导致代码丢失</p><p>解决方法：</p><p>使用 git stash ，将当前的修改存到暂存区，切换分支后，再 git stash pop 取出暂存区的内容，然后进行提交。</p><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260506020709071.png" alt="image-20260506020709071" referrerpolicy="no-referrer" loading="lazy"></p><p>明白了，您问的是：执行 <code>git stash pop</code> 之后，原来在 stash 里的那条记录（比如 <code>stash@{0}</code>）还在不在？</p><p class="pseudo-heading"><strong>答案：不在了。</strong></p><ul><li><code>git stash pop</code> = <code>git stash apply</code> + <code>git stash drop</code> 它会<strong>应用</strong>最新的 stash 内容到当前工作区，然后<strong>删除</strong>该 stash 条目。</li><li>如果您想保留 stash 记录方便以后再用，应该使用 <code>git stash apply</code>（应用但不删除），之后可以再用 <code>git stash drop</code> 手动删除。</li></ul><blockquote><p>验证方法： 执行 <code>git stash list</code> 看看剩下的 stash 列表。如果 pop 之前只有一个条目，pop 之后 <code>git stash list</code> 会为空。</p></blockquote><p>所以关于您之前问的“staged 中的缓存还在吗”——您这里指的其实是 <strong>stash 里面保存的修改记录</strong>。 答案是：<strong>pop 之后就不在了</strong>，已经被整体取出来并删除了。</p><h3 id="创建分支失败" tabindex="-1">创建分支失败 <a class="header-anchor" href="#创建分支失败" aria-label="Permalink to &quot;创建分支失败&quot;">​</a></h3><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260506030816373.png" alt="image-20260506030816373" referrerpolicy="no-referrer" loading="lazy"></p><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/74dada37b512c2ceb461dd4bc1c64f2e.png" alt="74dada37b512c2ceb461dd4bc1c64f2e" referrerpolicy="no-referrer" loading="lazy"></p><p><img src="https://gitee.com/Seniorsy/pic-go/raw/master/typora/image-20260506030753680.png" alt="image-20260506030753680" referrerpolicy="no-referrer" loading="lazy"></p>',17)])])}const m=e(r,[["render",p]]);export{h as __pageData,m as default};
